import { useState } from "react";
import QRCode from "react-qr-code";
import { IndianRupee, Loader2, ShieldCheck, X } from "lucide-react";
import { confirmPayment } from "../../api/payments.api";

export default function PaymentModal({
  isOpen,
  onClose,
  module,
  itemName,
  amount,
  referenceId,
  onSuccess
}) {
  const [method, setMethod] = useState("UPI");
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  // Formats the UPI string to auto-fill amount and payee details
  const upiString = `upi://pay?pa=neighborhub@upi&pn=NeighborHub&am=${amount}&cu=INR`;

  const processPayment = async () => {
    try {
      setLoading(true);

      // Calls the unified /confirm route
      await confirmPayment(module, referenceId, amount, method);

      // Triggers the UI refresh in the parent component
      onSuccess();

    } catch (err) {
      // ✅ FIXED: Accurately reads the error string from apiFetch
      alert(err.message || "Payment failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-in fade-in duration-200">

      <div className="bg-white w-full max-w-md rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">

        {/* Header */}
        <div className="bg-slate-50 px-6 py-4 border-b border-slate-100 flex justify-between items-center">
          <div className="flex items-center gap-2 text-indigo-600">
            <ShieldCheck size={24} />
            <h2 className="text-lg font-bold text-slate-800 tracking-tight">Secure Checkout</h2>
          </div>
          <button 
            onClick={onClose} 
            disabled={loading} 
            className="text-slate-400 hover:text-slate-600 hover:bg-slate-200 p-1.5 rounded-full transition-colors"
          >
            <X size={20} />
          </button>
        </div>

        <div className="p-6 sm:p-8">
          {/* Invoice Summary */}
          <div className="text-center mb-8">
            <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-2">{module}</p>
            <h3 className="text-xl font-semibold text-slate-800 leading-tight">{itemName}</h3>
            <div className="flex items-center justify-center gap-1 text-4xl font-black text-indigo-600 mt-4">
              <IndianRupee size={28} strokeWidth={3} />
              {amount}
            </div>
          </div>

          {/* Payment Method Selector */}
          <div className="flex gap-3 mb-8 bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
            <button
              onClick={() => setMethod("UPI")}
              className={`flex-1 py-2.5 rounded-xl font-semibold text-sm transition-all duration-200 ${
                method === "UPI" 
                  ? "bg-white text-indigo-700 shadow-sm border border-slate-200/50" 
                  : "text-slate-500 hover:text-slate-700"
              }`}
            >
              UPI / QR
            </button>
            <button
              onClick={() => setMethod("CASH")}
              className={`flex-1 py-2.5 rounded-xl font-semibold text-sm transition-all duration-200 ${
                method === "CASH" 
                  ? "bg-white text-indigo-700 shadow-sm border border-slate-200/50" 
                  : "text-slate-500 hover:text-slate-700"
              }`}
            >
              Cash at Office
            </button>
          </div>

          {/* UPI Flow */}
          {method === "UPI" && (
            <div className="text-center flex flex-col items-center animate-in slide-in-from-right-2 duration-300">
              <div className="bg-white p-4 rounded-2xl border-2 border-slate-100 shadow-sm inline-block mb-4">
                <QRCode value={upiString} size={160} className="text-slate-800" />
              </div>
              <p className="text-xs font-medium text-slate-400 mb-6">Scan with GPay, PhonePe, or Paytm</p>

              <button
                onClick={processPayment}
                disabled={loading}
                className="w-full bg-slate-900 hover:bg-slate-800 text-white font-bold py-3.5 rounded-xl transition-colors shadow-md flex justify-center items-center"
              >
                {loading ? <Loader2 className="animate-spin" size={20} /> : "I Have Paid"}
              </button>
            </div>
          )}

          {/* Cash Flow */}
          {method === "CASH" && (
            <div className="text-center animate-in slide-in-from-left-2 duration-300">
              <div className="bg-indigo-50 border border-indigo-100 rounded-2xl p-6 mb-6">
                <p className="text-sm font-medium text-indigo-800">
                  Please pay the exact amount at the community management office to confirm your booking.
                </p>
              </div>
              <button
                onClick={processPayment}
                disabled={loading}
                className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-3.5 rounded-xl transition-colors shadow-md flex justify-center items-center"
              >
                {loading ? <Loader2 className="animate-spin" size={20} /> : `Confirm Cash Payment`}
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
